func (this *Test_org_eclipse_swt_widgets_Shell) AssertShellProperlySized(shellLike swt.ShellLike, expectedSizeLike swt.PointLike) {
	var shell *swt.Shell
	if shellLike != nil {
		shell = shellLike.AsShell()
	}
	_ = shell
	var expectedSize *swt.Point
	if expectedSizeLike != nil {
		expectedSize = expectedSizeLike.AsPoint()
	}
	_ = expectedSize
	var tolerance int32
	if shell.GetZoom() != 100 {
		tolerance = 1
	} else {
		tolerance = 0
	}
	var actualSize *swt.Point = shell.GetSize()
	abs71 := expectedSize.X - actualSize.X
	if abs71 < 0 {
		abs71 = -abs71
	}
	junit.AssertTrue(abs71 <= tolerance && func() bool {
		abs72 := expectedSize.Y - actualSize.Y
		if abs72 < 0 {
			abs72 = -abs72
		}
		return abs72 <= tolerance
	}(), fmt.Sprintf("%s%v ± %d, actual size: %v)", fmt.Sprintf("Shell is not sized correctly (expected size: "), expectedSize, tolerance, actualSize))
}

